html:
{#
  Sales Invoice Print Format (Custom HTML / Jinja) - v3
  Setup: Print Format > New > DocType: Sales Invoice > Type: Jinja (tick Custom Format).
  Set Margin Top = 12.7 mm (0.5 inch) in the Print Format page settings.
  Terms, return policy and bank details come from the Terms and Conditions (tc_name) on the invoice.
#}

{%- set doc_title = "SALES INVOICE" -%}
{%- set copy_label = "Original" -%}
{# Set to 1 only if you print on plain paper (no letterhead) #}
{%- set show_company_header = 0 -%}

{%- set tc_html = doc.terms -%}
{%- if not tc_html and doc.tc_name -%}
  {%- set tc_html = frappe.db.get_value("Terms and Conditions", doc.tc_name, "terms") -%}
{%- endif -%}

<style>
  .inv { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #1a1a1a; margin: 0; padding: 0; }
  .inv table { width: 100%; border-collapse: collapse; }
  .inv td, .inv th { vertical-align: top; }

  .inv .co-name { font-size: 15px; font-weight: 700; margin-bottom: 2px; }
  .inv .co-addr { font-size: 11px; line-height: 1.4; }

  .inv .title { text-align: right; font-size: 18px; font-weight: 700; letter-spacing: .5px;
                border-right: 6px solid #1a1a1a; padding-right: 8px; line-height: 1.1; }
  .inv .copy { text-align: right; font-size: 10px; color: #555; margin: 3px 14px 0 0; }

  .inv .cust-lbl { font-size: 9px; color: #777; margin-bottom: 1px; }
  .inv .cust-name { font-size: 13px; font-weight: 700; margin-bottom: 2px; }
  .inv .cust-addr { font-size: 11px; line-height: 1.4; }

  /* Document details: label and value close together */
  .inv table.meta { width: auto; }
  .inv .meta td { padding: 1.5px 0; font-size: 11px; white-space: nowrap; }
  .inv .meta .k { color: #555; padding-right: 8px; }
  .inv .meta .v { font-weight: 700; text-align: left; }

  .inv .items { margin-top: 12px; table-layout: fixed; }
  .inv .items th { text-align: left; font-size: 11px; font-weight: 700;
                   border-top: 1px solid #1a1a1a; border-bottom: 1px solid #1a1a1a; padding: 5px 4px; }
  .inv .items th.r { text-align: right; }
  .inv .items td { padding: 4px 4px; border-bottom: 1px dotted #bbb; }
  .inv .items td.desc { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .inv .r { text-align: right; }
  .inv .sn { color: #999; font-size: 9px; }

  .inv .terms { font-size: 10.5px; line-height: 1.5; padding-right: 20px; }
  .inv .terms p, .inv .terms div { margin: 0; }

  /* Totals: label and amount close together */
  .inv table.totals { width: auto; }
  .inv .totals td { padding: 3px 0; font-size: 11px; white-space: nowrap; }
  .inv .totals td.k { padding-right: 8px; }
  .inv .totals td.n { text-align: right; min-width: 95px; }
  .inv .totals .grand td { border-top: 1px solid #1a1a1a; font-weight: 700; font-size: 12px; padding-top: 6px; }

  .inv .words { font-size: 10px; margin-top: 8px; font-style: italic; }
  .inv .sign { margin-top: 30px; }
  .inv .sign td { width: 33%; text-align: center; font-size: 10px; padding-top: 22px; }
  .inv .sign .line { border-top: 1px solid #1a1a1a; padding-top: 3px; margin: 0 14px; }
</style>

<div class="inv">

  {% if show_company_header %}
  <div style="margin-bottom:8px;">
    <div class="co-name">{{ doc.company }}</div>
    <div class="co-addr">{{ doc.company_address_display or "" }}{% if doc.company_tax_id %}<br>TIN: {{ doc.company_tax_id }}{% endif %}</div>
  </div>
  {% endif %}

  <!-- TITLE -->
  <table>
    <tr>
      <td style="width:60%"></td>
      <td style="width:40%">
        <div class="title">{{ doc_title }}</div>
        <div class="copy">{{ copy_label }}</div>
      </td>
    </tr>
  </table>

  <!-- CUSTOMER (left)  |  DOCUMENT DETAILS (right) -->
  <table style="margin-top:6px;">
    <tr>
      <td style="width:58%; padding-right:16px;">
        <div class="cust-lbl">Customer</div>
        <div class="cust-name">{{ doc.customer_name }}</div>
        <div class="cust-addr">
          {{ doc.address_display or "" }}
          {% if doc.tax_id %}<br>TIN: {{ doc.tax_id }}{% endif %}
        </div>
      </td>
      <td style="width:42%">
        <table class="meta">
          <tr><td class="k">Invoice No:</td><td class="v">{{ doc.name }}</td></tr>
          <tr><td class="k">Trx Date:</td><td class="v">{{ frappe.utils.formatdate(doc.posting_date, "dd.MM.yyyy") }}</td></tr>
          <tr><td class="k">Due Date:</td><td class="v">{{ frappe.utils.formatdate(doc.due_date, "dd.MM.yyyy") if doc.due_date else "-" }}</td></tr>
          <tr><td class="k">Salesperson:</td><td class="v">{{ (doc.sales_team[0].sales_person if doc.sales_team else "") or "-" }}</td></tr>
          <tr><td class="k">Customer PO:</td><td class="v">{{ doc.po_no or "-" }}</td></tr>
        </table>
      </td>
    </tr>
  </table>

  <!-- ITEMS -->
  <table class="items">
    <thead>
      <tr>
        <th style="width:4%"></th>
        <th style="width:12%">Item Code</th>
        <th style="width:42%">Description</th>
        <th class="r" style="width:9%">Quantity</th>
        <th class="r" style="width:15%">Price</th>
        <th class="r" style="width:18%">Total</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      <tr>
        <td class="sn">{{ "%03d"|format(loop.index) }}</td>
        <td class="desc">{{ row.item_code }}</td>
        <td class="desc">{{ row.item_name }}</td>
        <td class="r">{{ row.get_formatted("qty", doc) }}</td>
        <td class="r">{{ row.get_formatted("rate", doc) }}</td>
        <td class="r">{{ row.get_formatted("amount", doc) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <!-- TERMS (from tc_name) + TOTALS -->
  <table style="margin-top:16px;">
    <tr>
      <td style="width:58%">
        <div class="terms">{{ tc_html or "" }}</div>
      </td>
      <td style="width:42%">
        <table class="totals">
          <tr><td class="k">Invoice Subtotal:</td><td class="n">{{ doc.get_formatted("total", doc) }}</td></tr>
          {% if doc.discount_amount %}
          <tr><td class="k">Discount{% if doc.additional_discount_percentage %} ({{ doc.additional_discount_percentage }}%){% endif %}:</td>
              <td class="n">- {{ doc.get_formatted("discount_amount", doc) }}</td></tr>
          {% endif %}
          <tr><td class="k">Total Before Tax:</td><td class="n">{{ doc.get_formatted("net_total", doc) }}</td></tr>
          {% for tax in doc.taxes %}
          <tr><td class="k">{{ tax.description }}:</td><td class="n">{{ tax.get_formatted("tax_amount", doc) }}</td></tr>
          {% endfor %}
          <tr><td class="k">Total Tax Amount:</td><td class="n">{{ doc.get_formatted("total_taxes_and_charges", doc) }}</td></tr>
          <tr class="grand"><td class="k">Total Amount</td><td class="n">{{ doc.get_formatted("grand_total", doc) }}</td></tr>
          {% if doc.outstanding_amount is not none and doc.outstanding_amount != doc.grand_total %}
          <tr><td class="k">Outstanding:</td><td class="n">{{ doc.get_formatted("outstanding_amount", doc) }}</td></tr>
          {% endif %}
        </table>
      </td>
    </tr>
  </table>

  <div class="words">Amount in words: {{ doc.in_words }}</div>

  <!-- SIGNATURES -->
  <table class="sign">
    <tr>
      <td><div class="line">Prepared By</div></td>
      <td><div class="line">Authorised Signature</div></td>
      <td><div class="line">Customer Signature &amp; Date</div></td>
    </tr>
  </table>

</div>
